import * as React from 'react'
import { motion } from 'motion/react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'cn'
import { Tabs as TabsPrimitive } from 'radix-ui'
import { useMotionSettings } from '@/lib/motion'
const TabsContext = React.createContext({ value: '', id: '' })
function Tabs({
  className,
  orientation = 'horizontal',
  value,
  defaultValue,
  onValueChange,
  children,
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Root>) {
  const [internal, setInternal] = React.useState(defaultValue ?? '')
  const id = React.useId()
  const selected = value ?? internal
  return (
    <TabsContext.Provider value={{ value: selected, id }}>
      <TabsPrimitive.Root
        data-slot="tabs"
        orientation={orientation}
        value={selected}
        onValueChange={(v) => {
          setInternal(v)
          onValueChange?.(v)
        }}
        className={cn(
          'group/tabs flex gap-2 data-horizontal:flex-col',
          className,
        )}
        {...props}
      >
        {children}
      </TabsPrimitive.Root>
    </TabsContext.Provider>
  )
}
const tabsListVariants = cva(
  'relative inline-flex w-fit items-center justify-center gap-1 rounded-full p-1 text-muted-foreground',
  {
    variants: { variant: { default: 'bg-muted', line: 'bg-transparent' } },
    defaultVariants: { variant: 'default' },
  },
)
function TabsList({
  className,
  variant = 'default',
  ...props
}: React.ComponentProps<typeof TabsPrimitive.List> &
  VariantProps<typeof tabsListVariants>) {
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(tabsListVariants({ variant }), className)}
      {...props}
    />
  )
}
function TabsTrigger({
  className,
  children,
  value,
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Trigger>) {
  const context = React.useContext(TabsContext)
  const { enabled } = useMotionSettings()
  return (
    <TabsPrimitive.Trigger
      data-slot="tabs-trigger"
      value={value}
      className={cn(
        'relative flex flex-1 items-center justify-center gap-1.5 px-3 py-1.5 text-sm outline-none disabled:pointer-events-none disabled:opacity-50 focus-visible:ring-2 focus-visible:ring-ring',
        className,
      )}
      {...props}
    >
      {context.value === value && (
        <motion.span
          data-slot="tabs-indicator"
          layoutId={`tabs-${context.id}`}
          className="absolute inset-0 rounded-full bg-background"
          transition={
            enabled
              ? { type: 'spring', duration: 0.3, bounce: 0 }
              : { duration: 0 }
          }
        />
      )}
      <span className="relative z-10 flex items-center gap-1.5">
        {children}
      </span>
    </TabsPrimitive.Trigger>
  )
}
function TabsContent({
  className,
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Content>) {
  return (
    <TabsPrimitive.Content
      data-slot="tabs-content"
      className={cn('flex-1 text-sm outline-none', className)}
      {...props}
    />
  )
}
export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants }

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from 'react'
import { MotionConfig } from 'motion/react'
import { readPreference, savePreference } from './theme'
const MotionContext = createContext({
  paused: false,
  reduced: false,
  enabled: true,
  toggle: () => {},
})
const subscribeReduced = (notify: () => void) => {
  const media = matchMedia('(prefers-reduced-motion: reduce)')
  media.addEventListener('change', notify)
  return () => media.removeEventListener('change', notify)
}
export function MotionProvider({ children }: { children: ReactNode }) {
  const reduced = useSyncExternalStore(
    subscribeReduced,
    () => matchMedia('(prefers-reduced-motion: reduce)').matches,
    () => false,
  )
  const [paused, setPaused] = useState(
    () => readPreference('pds-motion', 'on') === 'off',
  )
  const enabled = !paused && !reduced
  useEffect(() => {
    document.documentElement.dataset.motion = enabled ? 'on' : 'off'
    savePreference('pds-motion', paused ? 'off' : 'on')
  }, [enabled, paused])
  return (
    <MotionContext.Provider
      value={{ paused, reduced, enabled, toggle: () => setPaused((p) => !p) }}
    >
      <MotionConfig
        reducedMotion={enabled ? 'never' : 'always'}
        transition={{ type: 'spring', duration: 0.3, bounce: 0 }}
      >
        {children}
      </MotionConfig>
    </MotionContext.Provider>
  )
}
export function useMotionSettings() {
  return useContext(MotionContext)
}
const subscribeTheme = (notify: () => void) => {
  const observer = new MutationObserver(notify)
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class'],
  })
  return () => observer.disconnect()
}
export function useResolvedTheme(): 'dark' | 'light' {
  return useSyncExternalStore<'dark' | 'light'>(
    subscribeTheme,
    () =>
      document.documentElement.classList.contains('dark') ? 'dark' : 'light',
    () => 'light',
  )
}

import { useEffect, useState } from 'react'
export type Theme = 'light' | 'dark' | 'system'
export function readPreference(key: string, fallback: string) {
  try {
    return localStorage.getItem(key) ?? fallback
  } catch {
    return fallback
  }
}
export function savePreference(key: string, value: string) {
  try {
    localStorage.setItem(key, value)
  } catch {
    /* Storage may be disabled. */
  }
}
export function useTheme() {
  const [theme, setTheme] = useState<Theme>(() => {
    const saved = readPreference('pds-theme', 'system')
    return saved === 'light' || saved === 'dark' ? saved : 'system'
  })
  useEffect(() => {
    const media = window.matchMedia('(prefers-color-scheme: dark)')
    const apply = () => {
      const dark = theme === 'dark' || (theme === 'system' && media.matches)
      document.documentElement.classList.toggle('dark', dark)
      document.documentElement.dataset.theme = dark ? 'dark' : 'light'
      document.documentElement.style.colorScheme = dark ? 'dark' : 'light'
    }
    apply()
    savePreference('pds-theme', theme)
    media.addEventListener('change', apply)
    return () => media.removeEventListener('change', apply)
  }, [theme])
  return [theme, setTheme] as const
}
